// DP：dp[i][j] = 以 (i, j) 為右下角的最大正方形邊長
// 時間複雜度: O(m·n)，空間複雜度: O(n)
function maximalSquare(matrix) {
    const m = matrix.length, n = matrix[0].length;
    const dp = new Array(n + 1).fill(0);
    let side = 0;
    for (let i = 1; i <= m; i++) {
        let prev = 0; // dp[i-1][j-1]
        for (let j = 1; j <= n; j++) {
            const tmp = dp[j];
            if (matrix[i - 1][j - 1] === '1') {
                dp[j] = Math.min(dp[j], dp[j - 1], prev) + 1;
                side = Math.max(side, dp[j]);
            }
            else {
                dp[j] = 0;
            }
            prev = tmp;
        }
    }
    return side * side;
}

