// DP：dp[i][j] = 以 (i, j) 為右下角的最大正方形邊長（滾動陣列）
// 時間複雜度: O(m·n)，空間複雜度: O(n)
int maximalSquare(char** matrix, int matrixSize, int* matrixColSize) {
    int n = matrixColSize[0];
    int* dp = calloc(n + 1, sizeof(int));
    int side = 0;
    for (int i = 1; i <= matrixSize; i++) {
        int prev = 0;                                 // dp[i-1][j-1]
        for (int j = 1; j <= n; j++) {
            int tmp = dp[j];
            if (matrix[i - 1][j - 1] == '1') {
                int m = dp[j] < dp[j - 1] ? dp[j] : dp[j - 1];
                if (prev < m) m = prev;
                dp[j] = m + 1;
                if (dp[j] > side) side = dp[j];
            } else {
                dp[j] = 0;
            }
            prev = tmp;
        }
    }
    free(dp);
    return side * side;
}
